/** Reviewed SNPS fiscal quarter plus an editable annual tail. No past YTD cash flow is revalued. */
import {incrementalRecord} from './incremental-registry.js';
export const SNPS_FUNDING_NOTE='FY2027 analyst funding floor = 290 USDm net physical capex + 8% of positive revenue growth from the selected FY2026 reference. Entered investment is retained; any top-up is added separately. This is a capacity assumption, not a contractual liability. The Q4 restructuring settlement is excluded.';
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const days=(a,b)=>(Date.parse(b+'T00:00:00Z')-Date.parse(a+'T00:00:00Z'))/86400000;
export function selectedSnpsCase(d){const r=incrementalRecord(d?.ticker);if(r?.bridge.type!=='snps-v3')return null;return d.selectedIncrementalScenario?r.alternatives.find(x=>x.name===d.selectedIncrementalScenario)?.annualCase:r.annualCase;}
export function snpsOpeningStubIssues(d){
 const c=selectedSnpsCase(d);if(!c)return ['SNPS requires its reviewed selected source case.'];
 const issues=[];
 if(!['openingStub','anchor','annualFundingPolicy'].every(k=>JSON.stringify(d[k])===JSON.stringify(c[k])))issues.push('Retain the selected SNPS Q4 stub, ACT/365.25 dates, mixed FY2026 reference and analyst funding-floor policy together.');
 if(Array.isArray(d.annual)&&d.annual.some((r,i)=>r?.period!==`FY${2027+i}`))issues.push('SNPS annual labels must retain their exact fiscal years ending October 31. Export the saved draft before restoring the reviewed case.');
 if(finite(d.annual?.[0]?.revenue)&&finite(d.annual?.[0]?.reinvestment)&&finite(d.anchor?.revenue)){const f=snpsAnnualFunding(d,0);if(Math.abs(f.enteredReinvestment+f.investmentFloorTopUp-f.reinvestment)>Math.max(1e-8,Math.abs(f.reinvestment)*1e-12))issues.push('SNPS investment magnitude loses precision in the funding-floor reconciliation. Reduce the entered magnitude; the saved value is retained.');}
 return issues;
}
export function snpsAnnualFunding(d,index,row=d.annual[index]){
 const p=selectedSnpsCase(d)?.annualFundingPolicy;if(!p)throw Error('SNPS source funding policy is unavailable.');
 const investmentFloor=index===0?p.physicalNetCapex+p.workingCapitalRate*Math.max(0,row.revenue-d.anchor.revenue):null;
 const enteredReinvestment=row.reinvestment,reinvestment=investmentFloor===null?enteredReinvestment:Math.max(enteredReinvestment,investmentFloor),investmentFloorTopUp=reinvestment-enteredReinvestment;
 return {enteredReinvestment,investmentFloor,investmentFloorTopUp,reinvestment};
}
export function snpsStubCalculation(d){const issues=snpsOpeningStubIssues(d);if(issues.length)throw Error(issues.join(' '));const s=d.openingStub,ebit=s.revenue*s.operatingMargin,tax=Math.max(0,ebit)*s.taxRate,nopat=ebit-tax,fcff=nopat-s.reinvestment-s.legacyRestructuringCash,discountFactor=(1+s.wacc)**s.durationYears;return {...s,ebit,tax,nopat,fcff,discountFactor,pv:fcff/discountFactor,yearsFromOrigin:s.durationYears,classification:'Fixed selected Q4 source cash flows, restructuring settlement and discount rate; annual-tail sensitivities exclude this quarter.'};}
export function calculateSnpsOperating(d){
 const openingStub=snpsStubCalculation(d);let prior=d.anchor.revenue,previousEnd='2026-10-31',discount=openingStub.discountFactor,pv=openingStub.pv,cumulative=openingStub.fcff,trough=Math.min(0,cumulative);
 const rows=d.annual.map((r,index)=>{const funding=snpsAnnualFunding(d,index,r),periodEnd=`${2027+index}-10-31`,durationYears=days(previousEnd,periodEnd)/365.25,yearsFromOrigin=days('2026-07-31',periodEnd)/365.25,ebit=r.revenue*r.margin,tax=Math.max(0,ebit)*r.taxRate,nopat=ebit-tax,fcff=nopat-funding.reinvestment;discount*=(1+r.wacc)**durationYears;const presentValue=fcff/discount;pv+=presentValue;cumulative+=fcff;trough=Math.min(trough,cumulative);const growth=r.revenue/prior-1,deltaRevenue=r.revenue-prior;prior=r.revenue;previousEnd=periodEnd;if(![...Object.values(funding).filter(x=>x!==null),ebit,tax,nopat,fcff,discount,presentValue,pv,growth].every(finite))throw Error('SNPS annual-tail arithmetic exceeded the finite numerical range.');return {...r,...funding,growth,ebit,tax,nopat,fcff,discountFactor:discount,pv:presentValue,cumulativeFCFF:cumulative,yearsFromOrigin,durationYears,periodEnd,derivedSalesCapital:funding.reinvestment!==0?deltaRevenue/funding.reinvestment:null};});
 const t=d.terminal,last=rows.at(-1),revenue=last.revenue*(1+t.growth),ebit=revenue*t.margin,nopat=ebit*(1-t.taxRate),reinvestment=nopat*t.growth/t.roic,fcff=nopat-reinvestment,value=fcff/(t.wacc-t.growth),terminalPV=value/discount,enterprise=pv+terminalPV;
 if(![revenue,ebit,nopat,reinvestment,fcff,value,terminalPV,enterprise].every(finite))throw Error('SNPS terminal arithmetic exceeded the finite numerical range.');
 const terminal={...t,revenue,ebit,nopat,reinvestment,fcff,value,pv:terminalPV,discountFactor:discount,yearsFromOrigin:last.yearsFromOrigin,periodEnd:last.periodEnd,fcffGrowth:last.fcff!==0?fcff/last.fcff-1:null,revenueGrowthEndpointDifference:last.growth-t.growth};
 const warnings=['The selected Q4 2026 cash flows and stub WACC stay fixed. Annual edits and simulation affect FY2027 onward using actual fiscal dates / 365.25; source whole-curve WACC sensitivities differ.','The FY2026 reference combines actual nine-month earnings with normalized Q4. It is not fully normalized annual EBIT. Past nine-month cash flows are not valued again.','The FY2027 investment floor is an analyst capacity and working-capital assumption, not a contractual claim. Any top-up is shown separately from entered investment.'];
 if(terminal.fcffGrowth===null||Math.abs(terminal.fcffGrowth-t.growth)>1e-6)warnings.push('Final explicit FCFF and terminal FCFF do not grow at the stable revenue rate. Inspect the capital-transition sensitivity; the original research path is preserved.');
 if(Math.abs(terminal.revenueGrowthEndpointDifference)>1e-6)warnings.push('Final explicit revenue growth differs from terminal growth. The growth endpoint change is separate from the capital transition.');
 return {ticker:d.ticker,currency:d.currency,informationAsOf:d.informationAsOf,discountOrigin:d.discountOrigin,openingStub,rows,terminal,forecastPV:pv,annualTailPV:pv-openingStub.pv,terminalPV,enterprise,terminalShare:enterprise>0?terminalPV/enterprise:null,peakEconomicDeficit:Math.max(0,-trough),negativeFCFFYears:rows.filter(r=>r.fcff<0).length+(openingStub.fcff<0?1:0),warnings,classification:'Conditional July-origin operating research; fixed fiscal Q4 plus editable annual tail. October information, no current-price or as-known comparison.'};
}
